mapper.select:
select distinct t1.* from sleeplog t1, sleeplog t2, sleeplog t3 where t1.sleeptime < 100 and t2.sleeptime <8 and t3.sleeptime<8 and ( (DATEDIFF(t1.createtime,t2.createtime)= 1 and DATEDIFF(t1.createtime,t3.createtime) = 2 and DATEDIFF(t2.createtime,t3.createtime) =1) -- t1, t2, t3 or (DATEDIFF(t2.createtime,t1.createtime)= 1 and DATEDIFF(t2.createtime,t3.createtime) = 2 and DATEDIFF(t1.createtime,t3.createtime) =1) -- t2, t1, t3 or (DATEDIFF(t3.createtime,t2.createtime)= 1 and DATEDIFF(t3.createtime,t1.createtime) = 2 and DATEDIFF(t2.createtime,t1.createtime) =1) -- t2, t1, t3 )
and t1.hyid=#{hyid}
order by t1.id
